/**
 * 对话渲染系统 - 服务端数据同步 v1.0
 * 独立辅助脚本，不依赖主脚本版本更新
 * 
 * 功能：
 * 1. 扩展 avatarDB 原型，添加 syncToServer / restoreFromServer 方法
 * 2. 在对话气泡面板注入 "☁ 同步" 按钮
 * 3. 启动时自动检测并恢复服务端数据
 * 
 * 依赖：对话渲染系统 v7.1 (加载后 window.avatarDB 和 window.avatarManagerPanel 可用)
 */

// ████████████████████████████████████████████████████████████
// █  AvatarDB 原型扩展：服务端数据同步方法                   █
// ████████████████████████████████████████████████████████████

(function() {
  'use strict';

  // 等待主脚本加载完成
  function waitForDB(retries = 50) {
    return new Promise((resolve, reject) => {
      let count = 0;
      const check = () => {
        if (window.avatarDB && window.avatarDB.db) {
          resolve(window.avatarDB);
        } else if (count < retries) {
          count++;
          setTimeout(check, 200);
        } else {
          reject(new Error('对话渲染系统未加载，请确认主脚本已启用'));
        }
      };
      check();
    });
  }

  // 工具：Blob -> base64
  function blobToBase64(blob) {
    if (!blob) return null;
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result);
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  }

  // 工具：base64 -> Blob
  function base64ToBlob(dataUrl) {
    if (!dataUrl) return null;
    const parts = dataUrl.split(',');
    const mime = parts[0].match(/:(.*?);/)?.[1] || 'image/webp';
    const bytes = atob(parts[1]);
    const arr = new Uint8Array(bytes.length);
    for (let i = 0; i < bytes.length; i++) arr[i] = bytes.charCodeAt(i);
    return new Blob([arr], { type: mime });
  }

  // 扩展 AvatarDB 原型
  function extendAvatarDB(db) {
    // 常量（与主脚本一致）
    const STORE_AVATARS = 'avatars';
    const STORE_MOOD_AVATARS = 'mood_avatars';
    const STORE_LOCAL_FONTS = 'local_fonts';
    const STORE_CONFIG = 'config';
    const STORE_CG_GROUPS = 'cg_groups';
    const STORE_CG_IMAGES = 'cg_images';
    const SYNC_KEY = 'BubbleDialogue_ServerData';

    // 通用 getAll
    db._syncGetAll = function(storeName) {
      return new Promise((resolve, reject) => {
        const tx = this.db.transaction(storeName, 'readonly');
        const req = tx.objectStore(storeName).getAll();
        req.onsuccess = () => resolve(req.result || []);
        req.onerror = () => reject(new Error('_syncGetAll ' + storeName + ' 失败'));
      });
    };

    // 通用 clearStore
    db._syncClearStore = function(storeName) {
      return new Promise((resolve, reject) => {
        const tx = this.db.transaction(storeName, 'readwrite');
        const req = tx.objectStore(storeName).clear();
        req.onsuccess = () => resolve();
        req.onerror = () => reject(new Error('_syncClearStore ' + storeName + ' 失败'));
      });
    };

    // 导出全部数据
    db.exportFullData = async function() {
      await this._ensureDB();
      const avatars = await this._syncGetAll(STORE_AVATARS);
      const moodAvatars = await this._syncGetAll(STORE_MOOD_AVATARS);
      const fonts = await this._syncGetAll(STORE_LOCAL_FONTS);
      const config = await this.getAllConfig();
      const cgGroups = await this._syncGetAll(STORE_CG_GROUPS);
      const cgImages = await this._syncGetAll(STORE_CG_IMAGES);

      const exportData = {
        version: '7.1-sync',
        exportedAt: new Date().toISOString(),
        avatars: [],
        moodAvatars: [],
        fonts: [],
        cgGroups: cgGroups,
        cgImages: [],
        config: config
      };

      for (const r of avatars) {
        exportData.avatars.push({
          alias: r.alias, mimeType: r.mimeType, fileName: r.fileName,
          fileSize: r.fileSize, width: r.width, height: r.height,
          sourceUrl: r.sourceUrl, createdAt: r.createdAt, updatedAt: r.updatedAt,
          imageBase64: r.imageBlob ? await blobToBase64(r.imageBlob) : null
        });
      }

      for (const r of moodAvatars) {
        exportData.moodAvatars.push({
          id: r.id, charId: r.charId, alias: r.alias, moodId: r.moodId,
          mimeType: r.mimeType, fileName: r.fileName,
          fileSize: r.fileSize, width: r.width, height: r.height,
          sourceUrl: r.sourceUrl, createdAt: r.createdAt, updatedAt: r.updatedAt,
          imageBase64: r.imageBlob ? await blobToBase64(r.imageBlob) : null
        });
      }

      for (const r of fonts) {
        exportData.fonts.push({
          id: r.id, family: r.family, name: r.name,
          mimeType: r.mimeType, fileName: r.fileName, fileSize: r.fileSize,
          format: r.format, createdAt: r.createdAt,
          fontBase64: r.fontBlob ? await blobToBase64(r.fontBlob) : null
        });
      }

      for (const r of cgImages) {
        exportData.cgImages.push({
          id: r.id, group: r.group,
          mimeType: r.mimeType, fileName: r.fileName, fileSize: r.fileSize,
          imageBase64: r.imageBlob ? await blobToBase64(r.imageBlob) : null
        });
      }

      return exportData;
    };

    // 从数据还原
    db.restoreFromData = async function(importData) {
      if (!importData || importData.version !== '7.1-sync') {
        throw new Error('无效的同步数据格式');
      }
      await this._ensureDB();
      const tx = this.db.transaction(
        [STORE_AVATARS, STORE_MOOD_AVATARS, STORE_LOCAL_FONTS, STORE_CONFIG, STORE_CG_GROUPS, STORE_CG_IMAGES],
        'readwrite'
      );

      // 清空现有 stores
      await Promise.all([
        this._syncClearStore(STORE_AVATARS),
        this._syncClearStore(STORE_MOOD_AVATARS),
        this._syncClearStore(STORE_LOCAL_FONTS),
        this._syncClearStore(STORE_CG_GROUPS),
        this._syncClearStore(STORE_CG_IMAGES)
      ]);

      // 还原头像
      const avatarStore = tx.objectStore(STORE_AVATARS);
      for (const r of (importData.avatars || [])) {
        const record = { ...r };
        if (r.imageBase64) { record.imageBlob = base64ToBlob(r.imageBase64); delete record.imageBase64; }
        avatarStore.put(record);
      }

      // 还情绪差分
      const moodStore = tx.objectStore(STORE_MOOD_AVATARS);
      for (const r of (importData.moodAvatars || [])) {
        const record = { ...r };
        if (r.imageBase64) { record.imageBlob = base64ToBlob(r.imageBase64); delete record.imageBase64; }
        moodStore.put(record);
      }

      // 还原字体
      const fontStore = tx.objectStore(STORE_LOCAL_FONTS);
      for (const r of (importData.fonts || [])) {
        const record = { ...r };
        if (r.fontBase64) { record.fontBlob = base64ToBlob(r.fontBase64); delete record.fontBase64; }
        fontStore.put(record);
      }

      // 还原配置
      const configStore = tx.objectStore(STORE_CONFIG);
      for (const [key, value] of Object.entries(importData.config || {})) {
        configStore.put({ key, value });
      }

      // 还原 CG
      const cgGroupStore = tx.objectStore(STORE_CG_GROUPS);
      for (const r of (importData.cgGroups || [])) { cgGroupStore.put(r); }

      const cgImageStore = tx.objectStore(STORE_CG_IMAGES);
      for (const r of (importData.cgImages || [])) {
        const record = { ...r };
        if (r.imageBase64) { record.imageBlob = base64ToBlob(r.imageBase64); delete record.imageBase64; }
        cgImageStore.put(record);
      }

      return new Promise((resolve, reject) => {
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(new Error('数据恢复事务失败'));
      });
    };

    // 同步到服务端
    db.syncToServer = async function() {
      const data = await this.exportFullData();
      const jsonStr = JSON.stringify(data);
      const blob = new Blob([jsonStr], { type: 'application/json' });
      const base64 = await blobToBase64(blob);

      if (typeof window !== 'undefined' && window.extension_settings) {
        window.extension_settings.BubbleDialogue_ServerData = {
          timestamp: Date.now(),
          size: blob.size,
          data: base64
        };
        if (typeof window.saveSettingsDebounced === 'function') {
          window.saveSettingsDebounced();
        }
        return { success: true, size: blob.size };
      }
      throw new Error('无法访问 extension_settings，请刷新页面后重试');
    };

    // 从服务端恢复
    db.restoreFromServer = async function() {
      const serverData = window.extension_settings?.BubbleDialogue_ServerData;
      if (!serverData || !serverData.data) {
        throw new Error('服务端没有备份数据');
      }
      const jsonBlob = base64ToBlob(serverData.data);
      const text = await jsonBlob.text();
      const importData = JSON.parse(text);
      await this.restoreFromData(importData);
      return { success: true, timestamp: serverData.timestamp };
    };

    // 检查服务端是否有数据
    db.hasServerData = function() {
      try {
        const serverData = window.extension_settings?.BubbleDialogue_ServerData;
        return !!(serverData && serverData.data);
      } catch (e) { return false; }
    };

    // 获取本地数据统计
    db.getLocalDataStats = async function() {
      await this._ensureDB();
      const [avatars, moodAvatars, fonts, cgImages] = await Promise.all([
        this._syncGetAll(STORE_AVATARS),
        this._syncGetAll(STORE_MOOD_AVATARS),
        this._syncGetAll(STORE_LOCAL_FONTS),
        this._syncGetAll(STORE_CG_IMAGES)
      ]);
      return {
        avatarCount: avatars.length,
        moodAvatarCount: moodAvatars.length,
        fontCount: fonts.length,
        cgImageCount: cgImages.length,
        totalSize: [...avatars, ...moodAvatars, ...fonts, ...cgImages].reduce((s, r) => s + (r.fileSize || 0), 0)
      };
    };
  }

  // ████████████████████████████████████████████████████████████
  // █  UI 注入：在对话气泡面板添加同步按钮                      █
  // ████████████████████████████████████████████████████████████

  function injectSyncButton() {
    // 查找面板标题栏中的导出按钮
    const exportBtn = document.getElementById('bam-btn-export');
    if (!exportBtn) {
      setTimeout(injectSyncButton, 500);
      return;
    }

    // 避免重复注入
    if (document.getElementById('bam-btn-sync')) return;

    const syncBtn = document.createElement('button');
    syncBtn.id = 'bam-btn-sync';
    syncBtn.style.cssText = 'background:rgba(74,108,247,0.12); border:1px solid rgba(74,108,247,0.25); color:#b9c7ff; padding:6px 12px; border-radius:6px; cursor:pointer; font-size:12px;';
    syncBtn.textContent = '☁ 同步';

    syncBtn.addEventListener('click', async () => {
      if (!window.avatarDB) {
        alert('对话渲染系统未加载');
        return;
      }
      const db = window.avatarDB;
      const origText = syncBtn.textContent;
      syncBtn.disabled = true;
      syncBtn.textContent = '同步中...';
      try {
        const stats = await db.getLocalDataStats();
        if (stats.avatarCount === 0 && stats.fontCount === 0 && stats.cgImageCount === 0) {
          alert('没有需要同步的数据。请先上传头像或数据包。');
          return;
        }
        const msg = '确认同步到云端？\n头像: ' + stats.avatarCount + ' 张\n情绪差分: ' + stats.moodAvatarCount + ' 张\n字体: ' + stats.fontCount + ' 个\nCG图片: ' + stats.cgImageCount + ' 张\n总计: ' + (stats.totalSize / 1024 / 1024).toFixed(2) + ' MB\n\n同步后可在其他设备上恢复。';
        if (!confirm(msg)) return;
        const result = await db.syncToServer();
        alert('✅ 同步成功！\n数据大小: ' + (result.size / 1024 / 1024).toFixed(2) + ' MB\n\n在其他设备上打开此页面时将自动恢复。');
      } catch (err) {
        alert('❌ 同步失败: ' + err.message);
      } finally {
        syncBtn.disabled = false;
        syncBtn.textContent = origText;
      }
    });

    // 插入到导出按钮后面
    exportBtn.parentNode.insertBefore(syncBtn, exportBtn.nextSibling);
  }

  // ████████████████████████████████████████████████████████████
  // █  启动时自动恢复                                          █
  // ████████████████████████████████████████████████████████████

  async function autoRestore(db) {
    try {
      const hasData = db.hasServerData();
      if (!hasData) return;

      const stats = await db.getLocalDataStats();
      if (stats.avatarCount + stats.moodAvatarCount + stats.fontCount + stats.cgImageCount > 0) return;

      console.log('[BubbleSync] 检测到服务端备份，本地为空，询问恢复...');
      if (confirm('检测到云端备份数据，是否恢复？\n（会覆盖当前本地数据）')) {
        await db.restoreFromServer();
        console.log('[BubbleSync] 从服务端恢复成功');
        if (window.avatarManagerPanel && window.avatarManagerPanel._refreshList) {
          window.avatarManagerPanel._refreshList();
        }
        alert('✅ 数据恢复成功！\n已从云端同步头像、字体和CG图片。');
      }
    } catch (e) {
      console.warn('[BubbleSync] 自动恢复失败:', e);
    }
  }

  // ████████████████████████████████████████████████████████████
  // █  初始化入口                                              █
  // ████████████████████████████████████████████████████████████

  $(() => {
    waitForDB()
      .then(db => {
        extendAvatarDB(db);
        console.log('[BubbleSync] AvatarDB 扩展完成（syncToServer / restoreFromServer）');

        // 注入 UI
        injectSyncButton();

        // 自动恢复（延迟等待数据加载）
        setTimeout(() => autoRestore(db), 2000);
      })
      .catch(err => {
        console.warn('[BubbleSync] 初始化失败:', err.message);
      });
  });

})();
